# The imported Dragonflight Quest Log art in the client's proven RLE form: the
# two pages split into 512x512 tiles (texture.large_dimensions), the oversized
# source canvases no longer shipped.
quest_log_asset_sizes = {
    "QuestLogPageLeft-0-0.tga": (512, 512),
    "QuestLogPageLeft-1-0.tga": (512, 512),
    "QuestLogPageLeft-0-1.tga": (512, 512),
    "QuestLogPageLeft-1-1.tga": (512, 512),
    "QuestLogPageRight-0-0.tga": (512, 512),
    "QuestLogPageRight-0-1.tga": (512, 512),
    "QuestLogRedButton.tga": (256, 128),
}
for quest_log_source in ("QuestLogPageLeft.tga", "QuestLogPageRight.tga"):
    if os.path.isfile(os.path.join(
            ADDONS, "pandaQuest", "media", "Textures", "QuestLog", quest_log_source)):
        quest_log_asset_sizes[quest_log_source] = None
quest_log_assets_valid = True
for quest_log_asset, expected_size in quest_log_asset_sizes.items():
    quest_log_path = os.path.join(
        ADDONS, "pandaQuest", "media", "Textures", "QuestLog", quest_log_asset)
    if not os.path.isfile(quest_log_path):
        quest_log_assets_valid = False
        break
    with open(quest_log_path, "rb") as quest_log_file:
        quest_log_header = quest_log_file.read(18)
    actual_size = (
        int.from_bytes(quest_log_header[12:14], "little"),
        int.from_bytes(quest_log_header[14:16], "little"),
    )
    if (len(quest_log_header) != 18 or quest_log_header[2] != 10
            or quest_log_header[16] != 32 or quest_log_header[17] != 8
            or actual_size != expected_size):
        quest_log_assets_valid = False
        break
check("the imported Quest Log pages ship as 512x512 RLE tiles",
      quest_log_assets_valid,
      "STANDALONE_QUEST_LOG.pages draws these exact tiles")

unsafe_textures = []
for texture_folder, _, texture_names in os.walk(os.path.join(ADDONS, "pandaQuest", "media")):
    for texture_name in texture_names:
        if not texture_name.lower().endswith((".tga", ".blp")):
            continue
        with Image.open(os.path.join(texture_folder, texture_name)) as texture_image:
            texture_width, texture_height = texture_image.size
        if (texture_width > 512 or texture_height > 512
                or texture_width & (texture_width - 1)
                or texture_height & (texture_height - 1)):
            unsafe_textures.append(texture_name)
check("every shipped texture is a power of two and at most 512 px a side",
      unsafe_textures == [], ", ".join(unsafe_textures)
      + " (run tools/make_client_safe_textures.py)")

