check("gossip icons fill the square slot uncropped in both themes", rt.eval("""(function()
    -- A client icon draws whole: no texcoords, or the full 0..1 square.
    local function uncropped(icon)
        local c = icon.texCoord
        return c == nil or (c[1] == 0 and c[2] == 1 and c[3] == 0 and c[4] == 1)
    end
    local frame = PandaQuestDialogueFrame
    local icon = PandaQuestDialogueRow3.pandaQuestIcon
    local expected = 26 * PandaQuest.Client.QUEST_DIALOGUE_UNIT
    local original = frame.pandaQuestTheme
    PandaQuest.Client.SetQuestDialogueTheme(frame, 'parchment')
    local classic = math.abs(icon:GetWidth() - expected) < 0.01
        and math.abs(icon:GetHeight() - expected) < 0.01 and uncropped(icon)
    PandaQuest.Client.SetQuestDialogueTheme(frame, 'horde-light')
    local cinematic = math.abs(icon:GetWidth() - expected) < 0.01
        and math.abs(icon:GetHeight() - expected) < 0.01 and uncropped(icon)
    PandaQuest.Client.SetQuestDialogueTheme(frame, original)
    return classic and cinematic
end)()"""))
