check("the stock gossip window gets the same marks, and pandaUI keeps its own", rt.eval("""(function()
    local Client = PandaQuest.Client
    local function Row(index, kind, text)
        local button = CreateFrame('Button', 'GossipTitleButton' .. index, GossipFrame)
        local icon = button:CreateTexture(nil, 'BACKGROUND')
        setglobal('GossipTitleButton' .. index .. 'GossipIcon', icon)
        icon:SetWidth(16)
        icon:SetHeight(16)
        icon:SetTexture('Interface\\\\GossipFrame\\\\' .. kind .. 'QuestIcon')
        button.type = kind
        button:SetText(text)
        button:Show()
        return icon
    end
    local savedCount = NUMGOSSIPBUTTONS
    local savedHost = PandaUI
    NUMGOSSIPBUTTONS = 3
    PandaUI = nil
    local open = Row(1, 'Active', 'Open Task')
    local ready = Row(2, 'Active', 'Ready Task')
    local offer = Row(3, 'Available', 'A New Task')
    Client.MarkNativeGossipQuestRows()
    local marked = open.path == Client.ACTIVE_QUEST_TEXTURE
        and ready.path == Client.COMPLETE_QUEST_TEXTURE
        and math.abs(open:GetWidth() - 16 * 19 / 32) < 0.01
        and offer.path == 'Interface\\\\GossipFrame\\\\AvailableQuestIcon'
        and offer:GetWidth() == 16
    -- A reused row goes back to the stock shape.
    GossipTitleButton1.type = 'Available'
    open:SetTexture('Interface\\\\GossipFrame\\\\AvailableQuestIcon')
    Client.MarkNativeGossipQuestRows()
    local restored = open:GetWidth() == 16
    PandaUI = {}
    GossipTitleButton1.type = 'Active'
    open:SetTexture('Interface\\\\GossipFrame\\\\ActiveQuestIcon')
    Client.MarkNativeGossipQuestRows()
    local hosted = open.path == 'Interface\\\\GossipFrame\\\\ActiveQuestIcon'
    PandaUI = savedHost
    NUMGOSSIPBUTTONS = savedCount
    local index = 1
    while index <= 3 do
        getglobal('GossipTitleButton' .. index):Hide()
        setglobal('GossipTitleButton' .. index, nil)
        setglobal('GossipTitleButton' .. index .. 'GossipIcon', nil)
        index = index + 1
    end
    PQ_TEST_LOG = PQ_TEST_LOG_BEFORE_GOSSIP
    return marked and restored and hosted
end)()"""))
