rt.execute("""
    local dialogue = PandaQuest:GetModule('Dialogue')
    local frame = PandaQuestDialogueFrame
    local Client = PandaQuest.Client
    PQ_TEST_OPTIONS_SAVED_THEME = PandaQuestDB.dialogueTheme
    PandaQuestDB.dialogueTheme = 'minimal'
    PQ_TEST_GOSSIP_PROBABILISTIC = false
    PQ_TEST_GOSSIP_TEXT = 'Well met, traveller.'
    PQ_TEST_GOSSIP_ACTIVE = { 'Ready Task', 23 }
    PQ_TEST_GOSSIP_AVAILABLE = { 'A New Task', 17 }
    PQ_TEST_GOSSIP_OPTIONS = { 'Browse goods', 'vendor' }
    GossipFrame:Show()
    dialogue:OnDialogueEvent('GOSSIP_SHOW')
    dialogue.closed = nil
    dialogue:Refresh()
    dialogue:FinishTextReveal()
    local box = Client.QUEST_DIALOGUE_LAYOUTS.minimal.conversation.optionButtons
    local third = PandaQuestDialogueOptionButton3
    PQ_TEST_OPTIONS = {
        body = frame.pandaQuestBody:GetText() or '',
        first = PandaQuestDialogueOptionButton1 and PandaQuestDialogueOptionButton1:IsShown(),
        third = third and third:IsShown() and third.pandaQuestLabel:GetText(),
        silver = third and third.pandaQuestSilver ~= nil and third.pandaQuestSilver.C:IsShown(),
        inCard = third and third.point[2] == frame,
        stack = PandaQuestDialogueRow1:IsShown() or PandaQuestDialogueOptionsScroll:IsShown(),
        height = frame:GetHeight(),
        expected = Client.GetQuestDialogueOptionsHeight(box, 3) * Client.QUEST_DIALOGUE_UNIT,
    }
    Client.SettleQuestDialogueLabels()
    Client.SettleQuestDialogueLabels()
    Client.SettleQuestDialogueLabels()
    local widest = 0
    for index = 1, 3 do
        local label = getglobal('PandaQuestDialogueOptionButton' .. index).pandaQuestLabel
        if label:GetWidth() > widest then widest = label:GetWidth() end
    end
    local hug = box.labelX + widest / Client.QUEST_DIALOGUE_UNIT + box.rightPad
    if hug < box.minWidth then hug = box.minWidth end
    PQ_TEST_OPTIONS.hugWidth = hug * Client.QUEST_DIALOGUE_UNIT
    PQ_TEST_OPTIONS.widths = { PandaQuestDialogueOptionButton1:GetWidth(),
        third:GetWidth() }
    PQ_TEST_OPTIONS.full = box.width * Client.QUEST_DIALOGUE_UNIT
    do
        local role = PandaQuestDialogueCineRole
        local ink = Client.QUEST_DIALOGUE_LAYOUTS.minimal.ink.title
        local red, green, blue = role:GetTextColor()
        PQ_TEST_OPTIONS.roleInk = role:IsShown() and role:GetText() ~= ''
            and math.abs(red - ink[1]) < 0.001 and math.abs(green - ink[2]) < 0.001
            and math.abs(blue - ink[3]) < 0.001
    end
    local cardWidth = 2 * box.x + hug
    if cardWidth < box.cardMinWidth then cardWidth = box.cardMinWidth end
    PQ_TEST_OPTIONS.cardWidth = frame:GetWidth()
    PQ_TEST_OPTIONS.cardExpected = cardWidth * Client.QUEST_DIALOGUE_UNIT
    local borders = frame.pandaQuestMinimalCards.card.borders
    PQ_TEST_OPTIONS.borderRight = borders.TR.points and borders.TR.points[1][4]
    PQ_TEST_OPTIONS.borderExpected = (cardWidth - Client.QUEST_DIALOGUE_MINIMAL.BORDER_SIZE)
        * Client.QUEST_DIALOGUE_UNIT
    local realSelect = dialogue.SelectRow
    dialogue.SelectRow = function(self, payload) PQ_TEST_OPTIONS.clicked = payload end
    third:GetScript('OnClick')()
    dialogue.SelectRow = realSelect
    PQ_TEST_GOSSIP_ACTIVE = {}
    PQ_TEST_GOSSIP_AVAILABLE = {}
    dialogue.lastSignature = nil
    dialogue:Refresh()
    dialogue:FinishTextReveal()
    dialogue.lastSignature = nil
    dialogue:Refresh()
    PQ_TEST_OPTIONS.plainBody = frame.pandaQuestBody:GetText() or ''
    PQ_TEST_OPTIONS.plainButtons = PandaQuestDialogueOptionButton1:IsShown()
    PQ_TEST_OPTIONS.plainHeight = frame:GetHeight()
    PQ_TEST_OPTIONS.plainWidth = frame:GetWidth()
    PQ_TEST_GOSSIP_TEXT = ''
    PQ_TEST_GOSSIP_OPTIONS = {}
    dialogue:Hide(false)
    GossipFrame:Hide()

    -- A greeting (several quests, no gossip) takes the buttons too.
    PQ_TEST_QUEST_GREETING_TEXT = 'Many tasks await.'
    PQ_TEST_SAVED_NUM_AVAILABLE = GetNumAvailableQuests
    function GetNumAvailableQuests() return 2 end
    function GetAvailableTitle(index) return index == 1 and 'First Errand' or 'Second Errand' end
    function GetAvailableLevel(index) return 5 end
    Client.ForgetSymbol('GetNumAvailableQuests')
    Client.ForgetSymbol('GetAvailableTitle')
    Client.ForgetSymbol('GetAvailableLevel')
    QuestFrame:Show()
    dialogue:OnDialogueEvent('QUEST_GREETING')
    dialogue.closed = nil
    dialogue:Refresh()
    dialogue:FinishTextReveal()
    PQ_TEST_OPTIONS.greetingBody = frame.pandaQuestBody:GetText() or ''
    PQ_TEST_OPTIONS.greetingSecond = PandaQuestDialogueOptionButton2:IsShown()
        and PandaQuestDialogueOptionButton2.pandaQuestLabel:GetText()
    PQ_TEST_OPTIONS.greetingThird = PandaQuestDialogueOptionButton3:IsShown()
    GetNumAvailableQuests = PQ_TEST_SAVED_NUM_AVAILABLE
    Client.ForgetSymbol('GetNumAvailableQuests')
    PQ_TEST_QUEST_GREETING_TEXT = ''
    dialogue:Hide(false)
    QuestFrame:Hide()

    -- A completed quest's objectives read with their log counts, and the
    -- Complete button grows to hold its label and key.
    local questState = PandaQuest:GetModule('QuestState')
    PQ_TEST_OPTIONS_REAL_BY_TITLE = questState.GetQuestByTitle
    questState.GetQuestByTitle = function(self, title)
        if title ~= 'Counted Quest' then return PQ_TEST_OPTIONS_REAL_BY_TITLE(self, title) end
        return { index = 2, objectives = {
            { text = 'Kobold Vermin slain: 10/10', objectiveType = 'monster', finished = true },
            { text = 'Candle: 6/6', objectiveType = 'item', finished = true },
        } }
    end
    PQ_TEST_QUEST_PACKET('Counted Quest', 'Do it.', 'Short words.')
    PQ_TEST_QUEST_PROGRESS_TEXT = ''
    PQ_TEST_QUEST_REWARD_TEXT = 'Well done.'
    PQ_TEST_QUEST_CHOICES = 0
    PQ_TEST_QUEST_REWARD_ITEMS = {}
    QuestFrame:Show()
    dialogue:OnDialogueEvent('QUEST_COMPLETE')
    dialogue.closed = nil
    dialogue:Refresh()
    dialogue:FinishTextReveal()
    Client.SettleQuestDialogueLabels()
    Client.SettleQuestDialogueLabels()
    Client.SettleQuestDialogueLabels()
    local action = PandaQuestDialogueAction
    local spec = Client.QUEST_DIALOGUE_MINIMAL.ACTION_BUTTON
    local centre = Client.QUEST_DIALOGUE_LAYOUTS.minimal.quest.actionButtonCentre
    local unit = Client.QUEST_DIALOGUE_UNIT
    local label = PandaQuestDialogueActionLabel
    local hint = action.pandaQuestHint
    PQ_TEST_OPTIONS.objective = dialogue.lastView and dialogue.lastView.objective
    PQ_TEST_OPTIONS.actionWidth = action:GetWidth()
    PQ_TEST_OPTIONS.actionNeeded = (label:GetWidth() + hint:GetWidth()) / unit
        + 2 * spec.HINT_PAD + spec.HINT_GAP
    PQ_TEST_OPTIONS.actionRight = action.point[4] + action:GetWidth() / 2
    -- Both keep their place from the card's right edge, which moves in when
    -- the card narrows to its content (Client.FitQuestDialogueCardWidth).
    local narrow = Client.GetQuestDialogueCardNarrowing(PandaQuestDialogueFrame)
    PQ_TEST_OPTIONS.narrowed = narrow > 0
    PQ_TEST_OPTIONS.actionRightExpected = (centre[1] - narrow + spec.WIDTH / 2) * unit
    local badge = PandaQuestDialogueFrame.pandaQuestCineKickerIcon
    local badgeBox = Client.QUEST_DIALOGUE_LAYOUTS.minimal.quest.kickerIcon
    PQ_TEST_OPTIONS.badgeTurnIn = badge:IsShown()
        and string.find(badge:GetTexture() or '', 'Kicker_Icon_TurnIn', 1, true) ~= nil
        and badge.points ~= nil and badge.points[1][1] == 'TOPLEFT'
        and math.abs(badge.points[1][4] - (badgeBox[1] - narrow) * unit) < 0.01
        and not PandaQuestDialogueCineKicker:IsShown()
    dialogue:Hide(false)
    PQ_TEST_QUEST_REWARD_TEXT = ''
    dialogue:OnDialogueEvent('QUEST_DETAIL')
    dialogue.closed = nil
    dialogue:Refresh()
    PQ_TEST_OPTIONS.badgeAccept = badge:IsShown()
        and string.find(badge:GetTexture() or '', 'Kicker_Icon_TurnIn', 1, true) == nil
        and string.find(badge:GetTexture() or '', 'Kicker_Icon', 1, true) ~= nil
    questState.GetQuestByTitle = PQ_TEST_OPTIONS_REAL_BY_TITLE
    PQ_TEST_QUEST_REWARD_TEXT = ''
    PandaQuestDB.dialogueTheme = PQ_TEST_OPTIONS_SAVED_THEME
    dialogue:Hide(false)
    QuestFrame:Hide()
""")
