check("Space drives the card and Esc closes it through a key frame held only while it is up",
      rt.eval("""(function()
    local dialogue = PandaQuest:GetModule('Dialogue')
    local frame = dialogue.frame
    local keys = PandaQuestDialogueKeys
    if not keys then return false end
    local savedMode, savedClick, savedEscape = dialogue.mode, frame.pandaQuestCardClick,
        frame.pandaQuestKeyEscape
    local clicked, escaped
    frame.pandaQuestCardClick = function(button) clicked = button end
    frame.pandaQuestKeyEscape = function() escaped = true end
    dialogue.mode = 'detail'
    frame:Show()
    dialogue:SyncKeyboard()
    local held = keys:IsShown()
    local handler = keys:GetScript('OnKeyDown')
    arg1 = 'SPACE'; handler()
    arg1 = 'W'; handler()
    local spaceOnly = clicked == 'LeftButton' and not escaped
    arg1 = 'ESCAPE'; handler()
    arg1 = nil
    PandaQuestDB.dialogueKeyboard = false
    dialogue:SyncKeyboard()
    local optedOut = not keys:IsShown()
    PandaQuestDB.dialogueKeyboard = nil
    dialogue:SyncKeyboard()
    local again = keys:IsShown()
    dialogue.mode = nil
    dialogue:SyncKeyboard()
    local released = not keys:IsShown()
    dialogue.mode, frame.pandaQuestCardClick, frame.pandaQuestKeyEscape =
        savedMode, savedClick, savedEscape
    return held and spaceOnly and escaped == true and optedOut and again and released
end)()"""))
check("the dialogue hides the HUD and world tooltip while up, pandaUI's only when loaded",
      rt.eval("""(function()
    local dialogue = PandaQuest:GetModule('Dialogue')
    local tracker = PandaQuest:GetModule('TrackerFrame')
    local native = CreateFrame('Frame', 'PlayerFrame', UIParent)
    local suppressed = CreateFrame('Frame', 'TargetFrame', UIParent)
    local bar = CreateFrame('Frame', 'PandaUIActionBar3', UIParent)
    native:Show() suppressed:Show() bar:Show()
    suppressed:SetAlpha(0)
    local savedMode, savedOption = dialogue.mode, PandaQuestDB.dialogueHideInterface
    local savedHost = PandaUI
    PandaUI = nil
    dialogue.mode = 'detail'
    dialogue.frame:Show()
    dialogue:SyncInterfaceHidden()
    local standalone = not native:IsShown() and bar:IsShown()
        and suppressed:IsShown() and tracker.suppressed == true
    PandaUI = {}
    dialogue:SyncInterfaceHidden()
    local hosted = not bar:IsShown()
    native:Show()
    dialogue:SyncInterfaceHidden()
    local rehidden = not native:IsShown()
    -- An owner's own Show() is hidden by its guard in the same script dispatch;
    -- the per-frame pass remains a fallback. A world hover's tooltip goes while
    -- a reward tile's stays.
    bar:Show()
    local onShow = bar:GetScript('OnShow')
    if onShow then onShow() end
    local guarded = not bar:IsShown()
    bar:Show()
    GameTooltip:SetOwner(UIParent, 'ANCHOR_NONE')
    GameTooltip:Show()
    PandaQuest.Client.KeepGameInterfaceHidden()
    local perFrame = not bar:IsShown() and not GameTooltip:IsShown()
    GameTooltip:SetOwner(dialogue.frame, 'ANCHOR_NONE')
    GameTooltip:Show()
    PandaQuest.Client.KeepGameInterfaceHidden()
    local ownTooltip = GameTooltip:IsShown()
    GameTooltip:Hide()
    PandaQuestDB.dialogueHideInterface = false
    dialogue:SyncInterfaceHidden()
    local optedOut = native:IsShown() and bar:IsShown() and not tracker.suppressed
    PandaQuestDB.dialogueHideInterface = savedOption
    dialogue:SyncInterfaceHidden()
    dialogue.mode = nil
    dialogue:SyncInterfaceHidden()
    local closed = native:IsShown() and bar:IsShown() and suppressed:IsShown()
        and not tracker.suppressed
    PandaUI = savedHost
    dialogue.mode = savedMode
    return standalone and hosted and rehidden and guarded and perFrame and ownTooltip
        and optedOut and closed
end)()"""))
