rt.execute("PQ_TEST_TICK(0.5, 60)")

# The passive smoothness census: frames over 25ms, deviation and jitter, split
# by moving and standing, so normal play shows sub-50ms beats.
check("the frame census counts 25ms frames and jitter, moving apart from still",
      rt.eval("""(function()
    local census = PandaQuest:GetModule('Driver'):GetFrameCensus()
    local movingBefore = census.moving.frames
    local overBefore = census.moving.over25
    PQ_TEST_MOVING = true
    PQ_TEST_TICK(0.3, 1)
    for _ = 1, 20 do
        PQ_TEST_TICK(0.01, 3)
        PQ_TEST_TICK(0.03, 1)
    end
    PQ_TEST_MOVING = false
    PQ_TEST_TICK(0.3, 1)
    PQ_TEST_TICK(1.1, 1)
    local saved = PandaQuestDB.driverStalls or {}
    return census.moving.frames >= movingBefore + 70
        and census.moving.over25 >= overBefore + 20
        and census.moving.jitter > 0 and census.still.frames > 0
        and type(saved.framesMoving) == 'string'
        and string.find(saved.framesMoving, 'over 25ms', 1, true) ~= nil
        and string.find(saved.framesMoving, 'jitter', 1, true) ~= nil
end)()"""))

