rt.execute("""
    local module = PandaQuest:GetModule('EntityTooltip')
    PQ_TEST_FADE_PRESENTATIONS = module.presentationCount
    PQ_TEST_FADE_COVER = true
    PQ_TEST_FADE_ALPHA = {}
    PandaUI.ModuleConfig = function() return { followCursor = true } end
    PQ_TEST_MOVE_CURSOR(100, 100)
    -- Real mouse-out ordering: the unit token disappears first while the
    -- native tooltip keeps the NPC's old first line through its fade. That
    -- stale name must not be mistaken for a cursor-follow world object.
    GameTooltip:SetAlpha(1)
    GameTooltipStatusBar:Show()
    GameTooltip:SetUnit('mouseover')
    GameTooltip:Show()
    module:Refresh()
    PandaQuestEntityTooltipModern.testLeft = 400
    PandaQuestEntityTooltipModern.testBottom = 300
    PQ_TEST_MOUSEOVER_NAME = nil
    -- Even a coordinated cursor-follow fade would become two composited boxes
    -- if the cover were made translucent over the native tooltip.
    local steps = { 1, 0.75, 0.5, 0.25, 0 }
    for step = 1, 5 do
        GameTooltip:SetAlpha(steps[step])
        GameTooltipStatusBar:SetAlpha(steps[step])
        module:Refresh()
        module:SyncFade()
        local panel = PandaQuestEntityTooltipModern
        if not panel.pandaQuestCover:IsShown() then PQ_TEST_FADE_COVER = false end
        PQ_TEST_FADE_ALPHA[step] = panel.pandaQuestAlpha
    end
""")
