print("minimap quest areas")
# The areas are clipped to the minimap circle before they are placed, because
# nothing clips a child of Minimap on this client. Every texture drawn must lie
# inside the circle, a patch wholly inside stays one texture, a patch wholly
# outside draws nothing, and a trimmed strip keeps its texels (u interpolated).
rt.execute("""
    PQ_TEST_AREA_PLACED = function(areas)
        local placed = {}
        -- Inside patches own a texture each and rim strips share a pool, so
        -- the drawn ones are the shown ones, in no particular order.
        for _, texture in ipairs(areas.textures) do
          if texture.pandaQuestPatchShown then
            local point = texture.points[table.getn(texture.points)]
            table.insert(placed, { left = point[4], top = point[5],
                width = texture.width, height = texture.height,
                u1 = texture.texCoord[1], u2 = texture.texCoord[2] })
          end
        end
        if table.getn(placed) ~= areas.visible then return {} end
        return placed
    end
""")
check("minimap areas never draw outside the minimap circle", rt.eval("""(function()
    local areas = PandaQuest:GetModule('MinimapAreas')
    areas.entries = { { quest = { titleKey = 'uqtestarea' },
        records = { { -100, -100, 100, 100, 0.1, 0.9 } },
        minX = -100, minY = -100, maxX = 100, maxY = 100 } }
    areas.lastProjectKey = nil
    areas:Project(0, 0, 1, 72, nil, nil, true)
    local radius = 70 + 1e-6
    local placed = PQ_TEST_AREA_PLACED(areas)
    if table.getn(placed) < 50 then return false end
    for _, rect in ipairs(placed) do
        local corners = {
            { rect.left, rect.top }, { rect.left + rect.width, rect.top },
            { rect.left, rect.top - rect.height },
            { rect.left + rect.width, rect.top - rect.height },
        }
        for _, corner in ipairs(corners) do
            if corner[1] * corner[1] + corner[2] * corner[2] > radius * radius then
                return false
            end
        end
    end
    return true
end)()"""))
check("a patch inside the circle is one texture; one outside draws nothing",
      rt.eval("""(function()
    local areas = PandaQuest:GetModule('MinimapAreas')
    areas.entries = {
        { quest = { titleKey = 'uqtestin' }, records = { { -5, -5, 5, 5, 0.2, 0.8 } },
          minX = -5, minY = -5, maxX = 5, maxY = 5 },
        { quest = { titleKey = 'uqtestout' }, records = { { 80, 80, 90, 90, 0.2, 0.8 } },
          minX = 80, minY = 80, maxX = 90, maxY = 90 },
    }
    areas.lastProjectKey = nil
    areas:Project(0, 0, 1, 72, nil, nil, true)
    local placed = PQ_TEST_AREA_PLACED(areas)
    return table.getn(placed) == 1 and placed[1].width == 10 and placed[1].height == 10
        and placed[1].left == -5 and placed[1].top == 5
        and placed[1].u1 == 0.2 and placed[1].u2 == 0.8
end)()"""))
check("a strip trimmed at the rim interpolates its texels", rt.eval("""(function()
    local areas = PandaQuest:GetModule('MinimapAreas')
    -- A wide one-strip patch through the centre, cut by the circle on both sides.
    areas.entries = { { quest = { titleKey = 'uqteststrip' },
        records = { { -100, -0.5, 100, 0.5, 0, 1 } },
        minX = -100, minY = -0.5, maxX = 100, maxY = 0.5 } }
    areas.lastProjectKey = nil
    areas:Project(0, 0, 1, 72, nil, nil, true)
    local placed = PQ_TEST_AREA_PLACED(areas)
    local rect = placed[1]
    local expected1 = (rect.left + 100) / 200
    local expected2 = (rect.left + rect.width + 100) / 200
    return table.getn(placed) == 1 and rect.left > -70 and rect.left < -69
        and math.abs(rect.u1 - expected1) < 1e-6 and math.abs(rect.u2 - expected2) < 1e-6
end)()"""))
check("only pinned or hovered quests draw, and an unchanged view is not redrawn",
      rt.eval("""(function()
    local areas = PandaQuest:GetModule('MinimapAreas')
    local owner = { hovered = nil }
    function owner:IsQuestAreaHovered(quest) return quest == self.hovered end
    local quest = { titleKey = 'uqtesthover' }
    areas.entries = { { quest = quest, records = { { -5, -5, 5, 5, 0.2, 0.8 } },
        minX = -5, minY = -5, maxX = 5, maxY = 5 } }
    areas.lastProjectKey = nil
    areas:Project(0, 0, 1, 72, owner, nil, false)
    local hiddenAtRest = areas.visible == 0
    owner.hovered = quest
    areas:Project(0, 0, 1, 72, owner, nil, false)
    local drawnTexture = areas.entries[1].records[1].texture
    local shownOnHover = areas.visible == 1 and drawnTexture ~= nil
        and drawnTexture.path == PandaQuest.Client.WORLD_MAP_AREA_CONTOUR_NEUTRAL_TEXTURE
    local key = areas.lastProjectKey
    areas:Project(0, 0, 1, 72, owner, nil, false)
    local cached = areas.lastProjectKey == key
    areas.entries = {}
    areas:HideAll()
    return hiddenAtRest and shownOnHover and cached and areas.visible == 0
end)()"""))
check("with an origin, a small step re-clips nothing and an inside patch is never re-anchored",
      rt.eval("""(function()
    local areas = PandaQuest:GetModule('MinimapAreas')
    local origin = PandaQuest:GetModule('MinimapPins'):GetPinOrigin()
    if not origin then return false end
    local quest = { titleKey = 'uqtestwalk' }
    -- One small patch near the centre, one wide band cut by the rim.
    local inside = { -5, -5, 5, 5, 0.2, 0.8 }
    areas.entries = { { quest = quest,
        records = { inside, { -100, 20, 100, 30, 0, 1 } },
        minX = -100, minY = -5, maxX = 100, maxY = 30 } }
    areas.lastProjectKey = nil
    areas:Project(0, 0, 1, 72, nil, nil, true, origin)
    local texture = inside.texture
    if not texture or areas.stripsShown == 0 then return false end
    local clips = areas.clip
    local anchorLeft = texture.pandaQuestPatchLeft
    areas:Project(0.5, 0, 1, 72, nil, nil, true, origin)
    local skipped = areas.clip == clips
    areas:Project(3, 0, 1, 72, nil, nil, true, origin)
    local reclipped = areas.clip == clips + 1
    local kept = inside.texture == texture and texture.pandaQuestPatchLeft == anchorLeft
        and texture.pandaQuestPatchAnchor == origin and texture.pandaQuestPatchShown
    areas.entries = {}
    areas:HideAll()
    return skipped and reclipped and kept and areas.visible == 0
        and inside.texture == nil
end)()"""))
check("the minimap rebuild takes its area geometry from the shared contour cache",
      rt.eval("""(function()
    local areas = PandaQuest:GetModule('MinimapAreas')
    local config = PandaQuest:GetModule('Config')
    local oldAreas = config:Get('mapObjectiveAreas')
    config:Set('mapObjectiveAreas', true)
    local quests = PandaQuest:GetModule('QuestState'):GetOrderedQuests()
    local yards = PandaQuest:GetModule('Database'):GetZoneYards(12)
    areas:Rebuild(quests, 12, yards[1], yards[2], config)
    PQ_TEST_TICK(0.05, 40)
    local built = table.getn(areas.entries) > 0 and table.getn(areas.buildQueue) == 0
    for _, entry in ipairs(areas.entries) do
        if not entry.records or table.getn(entry.records) == 0 then built = false end
    end
    config:Set('mapObjectiveAreas', false)
    areas:Rebuild(quests, 12, yards[1], yards[2], config)
    local cleared = table.getn(areas.entries) == 0
    config:Set('mapObjectiveAreas', oldAreas)
    return built and cleared
end)()"""))

print("minimap indoors")
# Indoors the minimap covers fewer yards at the same zoom step and this client
# exposes no way to learn how many, so the pins are withheld rather than drawn
# at a scale that makes them drift along with the player. The interior test is
# the disagreement between the zone the map shows and the area GetZoneText
# names: measured on this client, GetZoneText answers with the interior's own
# name inside a building ("Brill Town Hall", area 2118) and with the zone
# outdoors, even standing in the village of Brill, which is itself a subzone.
rt.execute("""
    PQ_TEST_INTERIOR_SAVED = {
        PQ_TEST_MAP_FILE, PQ_TEST_ZONE_NAME, PQ_TEST_MAP_ZONE_NAME, PQ_TEST_SUBZONE_NAME,
    }
    PQ_TEST_MAP_FILE = "Tirisfal"
    PQ_TEST_ZONE_NAME = "Tirisfal Glades"
    PQ_TEST_MAP_ZONE_NAME = "Tirisfal Glades"
    PQ_TEST_REAL_ZONE_NAME = nil
    local pins = PandaQuest:GetModule('MinimapPins')
    pins.dirty = true
    PQ_TEST_TICK(0.5, 4)
    PQ_TEST_INTERIOR_OUTSIDE = PandaQuest:GetModule('MapContext'):IsInterior()
    PQ_TEST_INTERIOR_STATE_OUT = pins.lastState
""")
check("standing in the open is not an interior", rt.eval(
    "PQ_TEST_INTERIOR_OUTSIDE == false and PQ_TEST_INTERIOR_STATE_OUT ~= 'interior'"))
rt.execute("""
    PQ_TEST_ZONE_NAME = "Brill Town Hall"
    PQ_TEST_REAL_ZONE_NAME = "Brill Town Hall"
    local pins = PandaQuest:GetModule('MinimapPins')
    pins.dirty = true
    PQ_TEST_TICK(0.5, 4)
    PQ_TEST_INTERIOR_INSIDE = PandaQuest:GetModule('MapContext'):IsInterior()
    PQ_TEST_INTERIOR_STATE_IN = pins.lastState
    PQ_TEST_INTERIOR_VISIBLE = pins.objectiveVisible + pins.giverVisible + pins.turnInVisible
""")
check("a building the map does not show is an interior", rt.eval(
    "PQ_TEST_INTERIOR_INSIDE == true"))
check("markers are withheld there rather than drawn at the wrong scale", rt.eval(
    "PQ_TEST_INTERIOR_STATE_IN == 'interior' and PQ_TEST_INTERIOR_VISIBLE == 0"))
check("the world map keeps drawing the zone the player is in", rt.eval(
    "PandaQuest:GetModule('MapContext'):GetCurrentZoneView() == 85"))
rt.execute("""
    PandaQuest:GetModule('Config'):Set('minimapPinsHideIndoors', false)
    local pins = PandaQuest:GetModule('MinimapPins')
    pins.dirty = true
    PQ_TEST_TICK(0.5, 4)
    PQ_TEST_INTERIOR_OPTOUT = pins.lastState
    PandaQuest:GetModule('Config'):Set('minimapPinsHideIndoors', true)
""")
check("the escape hatch draws them anyway", rt.eval(
    "PQ_TEST_INTERIOR_OPTOUT ~= 'interior'"))
rt.execute("""
    PQ_TEST_ZONE_NAME = "Tirisfal Glades"
    PQ_TEST_REAL_ZONE_NAME = nil
    local pins = PandaQuest:GetModule('MinimapPins')
    pins.dirty = true
    PQ_TEST_TICK(0.5, 4)
    PQ_TEST_INTERIOR_BACK = pins.lastState
    -- Every later section runs in Elwynn; put the client back where it was.
    PQ_TEST_MAP_FILE = PQ_TEST_INTERIOR_SAVED[1]
    PQ_TEST_ZONE_NAME = PQ_TEST_INTERIOR_SAVED[2]
    PQ_TEST_MAP_ZONE_NAME = PQ_TEST_INTERIOR_SAVED[3]
    PQ_TEST_SUBZONE_NAME = PQ_TEST_INTERIOR_SAVED[4]
    PandaQuest:GetModule('QuestState'):Scan()
    pins.dirty = true
    PandaQuest:GetModule('WorldMapPins').dirty = true
    PQ_TEST_TICK(0.5, 4)
""")
check("stepping back outside brings them straight back", rt.eval(
    "PQ_TEST_INTERIOR_BACK ~= 'interior'"))

print("minimap span calibration")
# The minimap's scale cannot be read back from Lua here -- nothing on it is a
# reference this addon did not draw itself -- so the only instrument is a
# player walking past a pin. "/pq minimap span" records what that instrument
# reads, keyed by area, zoom step and environment. Zoom 0 is known to fit
# Elwynn, while Stormwind was reported drifting at that same step; a correction
# in one area must not disturb the other.
rt.execute("""
    Minimap:SetZoom(3)
    PQ_TEST_TICK(1.0, 2)
    PQ_TEST_SPAN_BEFORE, PQ_TEST_SPAN_EVIDENCE_BEFORE =
        PandaQuest:GetModule('MinimapPins'):GetSpanForZoom(3, 12)
    SlashCmdList.PANDAQUEST('minimap span 240')
    PQ_TEST_SPAN_AFTER, PQ_TEST_SPAN_EVIDENCE_AFTER =
        PandaQuest:GetModule('MinimapPins'):GetSpanForZoom(3, 12)
    PQ_TEST_SPAN_OTHER_AREA, PQ_TEST_SPAN_OTHER_AREA_EVIDENCE =
        PandaQuest:GetModule('MinimapPins'):GetSpanForZoom(3, 1519)
""")
check("a dialled-in span replaces the constant for that zoom step", rt.eval(
    "PQ_TEST_SPAN_BEFORE == 266.6 and PQ_TEST_SPAN_EVIDENCE_BEFORE == 'vanillaConstant'"
    " and PQ_TEST_SPAN_AFTER == 240 and PQ_TEST_SPAN_EVIDENCE_AFTER == 'playerCalibrated'"))
check("it is stored where a reload will find it", rt.eval(
    "PandaQuestDB.minimapSpans ~= nil and PandaQuestDB.minimapSpans['12:out3'] == 240"))
check("the same zoom step in another area is untouched", rt.eval(
    "PQ_TEST_SPAN_OTHER_AREA == 266.6"
    " and PQ_TEST_SPAN_OTHER_AREA_EVIDENCE == 'vanillaConstant'"))
rt.execute("""
    Minimap:SetZoom(0)
    PQ_TEST_TICK(1.0, 2)
    PQ_TEST_SPAN_OTHER = PandaQuest:GetModule('MinimapPins'):GetSpanForZoom(0, 12)
""")
check("another zoom step is untouched by it", rt.eval("PQ_TEST_SPAN_OTHER == 466.6"))
rt.execute("""
    Minimap:SetZoom(3)
    PQ_TEST_TICK(1.0, 2)
    SlashCmdList.PANDAQUEST('minimap span reset')
    PQ_TEST_SPAN_RESET, PQ_TEST_SPAN_EVIDENCE_RESET =
        PandaQuest:GetModule('MinimapPins'):GetSpanForZoom(3, 12)
    Minimap:SetZoom(0)
    PQ_TEST_TICK(1.0, 2)
""")
check("reset returns that step to the constant", rt.eval(
    "PQ_TEST_SPAN_RESET == 266.6 and PQ_TEST_SPAN_EVIDENCE_RESET == 'vanillaConstant'"))

# Re-anchoring a pin dirties the client's layout even when nothing moved; at ten
# passes a second over every shown pin it was the zone-dependent stutter.
check("an unchanged shown minimap pin is not re-anchored, a hidden one is shown again", rt.eval("""(function()
    local Client = PandaQuest.Client
    local pin = CreateFrame("Button", nil, Minimap)
    local anchors = 0
    local realSetPoint = pin.SetPoint
    pin.SetPoint = function(self, a, b, c, d, e)
        anchors = anchors + 1
        return realSetPoint(self, a, b, c, d, e)
    end
    local placed = Client.PositionMinimapPin(pin, 12, -7)
    Client.PositionMinimapPin(pin, 12, -7)
    local afterSame = anchors
    Client.PositionMinimapPin(pin, 13, -7)
    local afterMove = anchors
    pin:Hide()
    Client.PositionMinimapPin(pin, 13, -7)
    return placed and afterSame == 1 and afterMove == 2 and anchors == 3 and pin:IsShown()
end)()"""))
print("minimap frozen player position")
# Every minimap offset is (target - player). A client that stops updating the
# player's map position while the player is walking turns the pins into a cloud
# that rides along with them, looking authoritative while describing nothing.
# Standing still is the ordinary reason for an unchanged position and must
# never hide the layer.
rt.execute("""
    PQ_TEST_MOVING = false
    PQ_TEST_PLAYER_POSITION = { 0.42, 0.65 }
    local pins = PandaQuest:GetModule('MinimapPins')
    pins.dirty = true
    PQ_TEST_TICK(0.5, 8)
    PQ_TEST_FROZEN_STILL = pins.lastState
""")
check("a stationary player never hides the minimap layer", rt.eval(
    "PQ_TEST_FROZEN_STILL ~= 'playerPositionStale'"))
rt.execute("""
    PQ_TEST_MOVING = true
    local pins = PandaQuest:GetModule('MinimapPins')
    PQ_TEST_TICK(0.5, 8)
    PQ_TEST_FROZEN_WALKING = pins.lastState
    PQ_TEST_FROZEN_VISIBLE = pins.objectiveVisible + pins.giverVisible + pins.turnInVisible
""")
check("a frozen position while walking hides the pins rather than dragging them", rt.eval(
    "PQ_TEST_FROZEN_WALKING == 'playerPositionStale' and PQ_TEST_FROZEN_VISIBLE == 0"))
rt.execute("""
    PQ_TEST_PLAYER_POSITION = { 0.43, 0.66 }
    local pins = PandaQuest:GetModule('MinimapPins')
    PQ_TEST_TICK(0.5, 4)
    PQ_TEST_FROZEN_RECOVERED = pins.lastState
""")
check("the layer comes straight back when the position moves again", rt.eval(
    "PQ_TEST_FROZEN_RECOVERED ~= 'playerPositionStale'"))
rt.execute("""
    PQ_TEST_MOVING = false
    PQ_TEST_PLAYER_POSITION = { 0.42, 0.65 }
    PQ_TEST_TICK(0.5, 4)
""")

print("minimap indoor detection")
# Indoors the minimap spans 300 yards at zoom 0, not 466.6. A layer using the
# outdoor row places every pin at about two thirds of its true distance, so the
