check("the minimap bag poll rebuilds only when its token changes", rt.eval("""(function()
    local pins = PandaQuest:GetModule('MinimapPins')
    local bags = PandaQuest:GetModule('BagItems')
    local driver = PandaQuest:GetModule('Driver')
    local job = driver and driver.jobsByName['map.minimappins.rebuild']
    if not pins or not bags or not job then return false end

    pins.relevantBagItemIds = { 999001 }
    pins.lastBagToken = bags:GetTokenFor(pins.relevantBagItemIds)
    pins.dirty = false
    job.callback()
    local unchangedStayedClean = pins.dirty == false

    local oldGetTokenFor = bags.GetTokenFor
    bags.GetTokenFor = function()
        return 'smokeChangedToken'
    end
    job.callback()
    local changedDirtied = pins.dirty == true
    bags.GetTokenFor = oldGetTokenFor
    pins.lastBagToken = bags:GetTokenFor(pins.relevantBagItemIds)
    pins:Refresh()
    return unchangedStayedClean and changedDirtied
end)()"""))
check("a bag cache key ignores items outside its dependency list", rt.eval("""(function()
    local bags = PandaQuest:GetModule('BagItems')
    local oldCarried, oldAvailable = bags.carried, bags.available
    bags.available = true
    bags.carried = { [999002] = true }
    local before = bags:GetTokenFor({ 999001 })
    bags.carried[999003] = true
    local unrelated = bags:GetTokenFor({ 999001 })
    bags.carried[999001] = true
    local relevant = bags:GetTokenFor({ 999001 })
    bags.carried, bags.available = oldCarried, oldAvailable
    return before == unrelated and relevant ~= unrelated
end)()"""))

# Lever 1, which this client has never offered: an arrow handed over as a Model
# child of Minimap is RAISED above the pins instead, exactly as the installed
# pfQuest does on Vanilla, and the pins stay in their measured band. Run last in
# this block because raising the arrow is a one-way answer for the session.
check("an arrow the client hands over is raised instead of lowering the pins",
      rt.eval("""(function()
    local client = PandaQuest.Client
    local pins = PandaQuest:GetModule('MinimapPins')
    local config = PandaQuest:GetModule('Config')
    local arrow = CreateFrame('Model', nil, Minimap)
    arrow.GetModel = function() return 'Interface\\\\Minimap\\\\MinimapArrow.mdx' end
    -- The real client answers with 7 children; the mock's Minimap is also the
    -- parent of every pooled pin, so the arrow is put where a real one is.
    table.insert(Minimap.children, 1, arrow)
    config:Set('minimapPinsBelowArrow', false)
    pins:Refresh()
    if client.FindMinimapPlayerArrow(true) ~= arrow then return false end
    config:Set('minimapPinsBelowArrow', true)
    pins.dirty = true
    pins:Refresh()
    local state = client.GetMinimapPlayerArrowState()
    return state.arrowFound == true and state.arrowRaised == true
        and arrow.frameLevel == 125
        and state.pinLevel == 120
        and pins.objectivePool[1].frameLevel == 120
end)()"""))

