check("area focus highlights both tracker rows at once", rt.eval("""(function()
    local pins = PandaQuest:GetModule('WorldMapPins')
    local job = PandaQuest:GetModule('Driver').jobsByName['map.questfocus']
    local quest = PQ_TEST_AREA.pandaQuestQuest
    local function highlighted(window)
        local rows = window.pandaQuestRows.quest
        for index = 1, table.getn(rows) do
            local row = rows[index]
            if row.pandaQuestSubject
                and row.pandaQuestSubject.titleKey == quest.titleKey then
                return row.pandaQuestHover:IsShown() == true
            end
        end
        return false
    end
    return pins.focusQuest == quest and not job.active
        and highlighted(PandaQuestTracker)
        and highlighted(PandaQuestMapTracker)
end)()"""))
