print("item-use objectives (obj.IR / quests-itemreq)")
# Marla's Last Wish (6395). obj.O names Marla's Grave (178090) at 31.2/65.1 in
# Tirisfal (85); obj.IR names Samuel's Remains (16333), and quests-itemreq maps
# that item onto the same grave. The grave is therefore the target of a "use
# this there" step, not an unconditional objective source, and it sits twenty
# yards from Novice Elreth (1661), the quest's own turn-in NPC -- which is
# exactly why drawing it from the moment the quest was accepted read as a
# second, bogus quest area over Deathknell.
check("an item-use target is recognised from obj.IR", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    local targets = db:GetQuestItemUseTargets(6395)
    if table.getn(targets) ~= 1 then return false end
    local t = targets[1]
    return t.itemId == 16333 and t.sourceType == 'object' and t.sourceId == 178090
end)()"""))
check("a quest with no obj.IR reports no item-use targets", rt.eval(
    "table.getn(PandaQuest:GetModule('Database'):GetQuestItemUseTargets(380)) == 0"))
check("static item-use targets are returned from the shared cache", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    return db:GetQuestItemUseTargets(6395) == db:GetQuestItemUseTargets(6395)
        and db:GetQuestItemUseTargets(380) == db:GetQuestItemUseTargets(380)
end)()"""))
check("neither half of an item-use step is an unconditional objective", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    local locations = db:GetQuestLocations(6395, nil, 85, 200)
    local sawGrave, sawSamuel = false, false
    for _, location in ipairs(locations) do
        if location.sourceType == 'object' and location.sourceId == 178090 then sawGrave = true end
        -- Samuel Fipps (1919) drops the remains. He is the step the player can
        -- take FIRST, not an objective in his own right, so the static walk
        -- leaves him to the bag-aware pass alongside the grave he leads to.
        if location.sourceType == 'unit' and location.sourceId == 1919 then sawSamuel = true end
    end
    return not sawSamuel and not sawGrave
end)()"""))
check("the required item's own sources are recognised", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    local items = db:GetQuestItemUseRequirementItems(6395)
    if not items[16333] then return false end
    local found = db:GetQuestItemUseSourceLocations(6395, 16333, 85)
    if table.getn(found) < 1 then return false end
    for _, location in ipairs(found) do
        if location.sourceType ~= 'unit' or location.sourceId ~= 1919 then return false end
    end
    -- An item that is a plain loot objective is not a requirement item, so its
    -- sources stay in the unconditional walk where they belong.
    return table.getn(db:GetQuestItemUseSourceLocations(6395, 5811, 85)) == 0
end)()"""))
# Proving Allegiance (409). The bundled data records only Lillith Nefara
# (1946) as the objective, and she is summoned, so her coords list is empty and
# the quest drew nothing at all. Database's DATA_FIXES declares the missing
# relations -- the Candle of Beckoning (3080) comes out of the Crate of Candles
# (object 1586) and is used on Lillith's Dinner Table (object 1557) -- which
# turns it into an ordinary item-use quest for every consumer downstream.
check("a recorded data gap is filled in at attach", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    local targets = db:GetQuestItemUseTargets(409)
    if table.getn(targets) ~= 1 then return false end
    local t = targets[1]
    if t.itemId ~= 3080 or t.sourceType ~= 'object' or t.sourceId ~= 1557 then
        return false
    end
    -- The crate is where the candle comes from, on the conditional path.
    local found = db:GetQuestItemUseSourceLocations(409, 3080, 85)
    if table.getn(found) ~= 1 then return false end
    return found[1].sourceType == 'object' and found[1].sourceId == 1586
end)()"""))
check("a filled gap adds no unconditional objective", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    local locations = db:GetQuestLocations(409, false, 85, 200)
    for _, location in ipairs(locations) do
        if location.sourceType == 'object'
            and (location.sourceId == 1557 or location.sourceId == 1586) then
            return false
        end
    end
    return true
end)()"""))
check("a map resize repositions cached contour patches without rebuilding them",
      rt.eval("""(function()
    local contours = PandaQuest:GetModule('AreaContours')
    local entry = contours.groups[1]
    local records = entry.patches
    local texture = entry.textures[1]
    local oldWidth = texture.width
    WorldMapButton:SetWidth(1200)
    contours:Reapply(true)
    local resized = entry.patches == records
        and math.abs(texture.width - oldWidth * 1.2) < 0.001
    WorldMapButton:SetWidth(1000)
    contours:Reapply(true)
    return resized and math.abs(texture.width - oldWidth) < 0.001
end)()"""))
check("interior contour patches sample the profile's flat fill end",
      rt.eval("""(function()
    local contours = PandaQuest:GetModule('AreaContours')
    local fill = 255.5 / 256
    for groupIndex = 1, contours.visibleCount do
        local entry = contours.groups[groupIndex]
        for patchIndex = 1, entry.visible do
            local patch = entry.patches[patchIndex]
            local texture = entry.textures[patchIndex]
            if patch[5] == fill and patch[6] == fill then
                return texture.path ~= nil and texture.texCoordArgs == 4
                    and texture.texCoord[1] == fill and texture.texCoord[2] == fill
                    and texture.texCoord[3] == 0.25 and texture.texCoord[4] == 0.75
            end
        end
    end
    return false
end)()"""))
# The geometry is built by the shared driver, off the frame that asked for it,
# and cached by layout so a redraw of the same area costs no geometry at all.
check("contour geometry is built off-frame and cached by layout", rt.eval("""(function()
    local contours = PandaQuest:GetModule('AreaContours')
    local driver = PandaQuest:GetModule('Driver')
    local job = driver.jobsByName['map.contours']
    local cached = 0
    for _ in pairs(contours.patchCache) do cached = cached + 1 end
    local pending = false
    for index = 1, contours.visibleCount do
        if contours.groups[index].pending then pending = true end
    end
    return job ~= nil and job.active == false and not pending
        and cached > 0 and cached == contours.patchCacheCount
        and table.getn(contours.buildQueue) == 0
end)()"""))
# Snatch and Grab (2206). The Defias Shipping Schedule (7675) has no source
# in the bundled item record, despite the quest directing the player to the
# Defias Dockmaster (6846). The data fix restores the ordinary item source, so
# every map consumer gets the Westfall dot without a quest-specific renderer.
check("an ordinary item source gap draws the Defias Dockmaster", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    local locations = db:GetQuestLocations(2206, false, 12, 8)
    if table.getn(locations) ~= 1 then return false end
    local location = locations[1]
    if location.sourceType ~= 'unit' or location.sourceId ~= 6846
        or location.x ~= 48.1 or location.y ~= 87.3 then
        return false
    end
    local areas = db:GetQuestAreaIds(2206, false)
    return table.getn(areas) == 1 and areas[1] == 12
end)()"""))
# Frostmaw (quest 1136 / creature 4504). obj.I names both the Fresh Carcass
# (5810) and Frostmaw's Mane (5811); only the Mane is an objective. The Carcass
# is bait used on the Growless Cave object (19876) and dropped by four Mountain
# Lion species carrying 72 spawns in Alterac, which is what buried Frostmaw's
# single summon coordinate.
check("bait sources leave the quest's own target alone on the map", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    local locations = db:GetQuestLocations(1136, false, 36, 200)
    local sawFrostmaw, others = 0, 0
    for _, location in ipairs(locations) do
        if location.sourceType == 'unit' and location.sourceId == 4504 then
            sawFrostmaw = sawFrostmaw + 1
        else
            others = others + 1
        end
    end
    return sawFrostmaw == 1 and others == 0
end)()"""))
check("the bait is still findable while it is not carried", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    local target = PandaQuest:GetModule('QuestTarget')
    local bags = PandaQuest:GetModule('BagItems')
    PQ_TEST_BAGS = { [0] = {} }
    bags:Invalidate()
    PQ_TEST_TICK(1.0, 8)
    local empty = target:CollectLocations({ questId = 1136 }, 36, false)
    PQ_TEST_BAGS[0][1] = 5810
    bags:Invalidate()
    PQ_TEST_TICK(1.0, 8)
    local carrying = target:CollectLocations({ questId = 1136 }, 36, false)
    local sawCave = false
    for _, location in ipairs(carrying) do
        if location.sourceType == 'object' and location.sourceId == 19876 then sawCave = true end
    end
    -- Empty bags: Frostmaw plus every lion. Carcass in hand: Frostmaw plus the
    -- one place it is used, and not a lion in sight.
    return table.getn(empty) > 60 and table.getn(carrying) == 2 and sawCave
end)()"""))
check("the turn-in relation is untouched by the exclusion", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    local locations = db:GetQuestLocations(6395, true, 85, 8)
    return table.getn(locations) == 1 and locations[1].sourceId == 1661
        and locations == db:GetQuestLocations(6395, true, 85, 8)
end)()"""))
check("an absent quest relation is cached as an empty answer", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    local oldFinishers = db.GetQuestFinishers
    local calls = 0
    db.GetQuestFinishers = function()
        calls = calls + 1
        return nil
    end
    local first = db:GetQuestLocations(987654, true, 12, 137)
    local second = db:GetQuestLocations(987654, true, 12, 137)
    db.GetQuestFinishers = oldFinishers
    return calls == 1 and first == second and table.getn(first) == 0
end)()"""))
check("entity locations honour the area filter", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    return table.getn(db:GetEntityLocations('object', 178090, 85, 8)) == 1
        and table.getn(db:GetEntityLocations('object', 178090, 1, 8)) == 0
end)()"""))
check("quest objective collection has no 200-location ceiling", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    local target = PandaQuest:GetModule('QuestTarget')
    local oldSources = db.GetQuestObjectiveSources
    local oldUnit = db.GetUnit
    local coordinates = {}
    local index = 1
    while index <= 205 do
        table.insert(coordinates, { 20 + index / 1000, 30, 12 })
        index = index + 1
    end
    db.GetQuestObjectiveSources = function(self, questId)
        if questId == 987650 then
            return { U = { 987651 } }
        end
        return oldSources(self, questId)
    end
    db.GetUnit = function(self, unitId)
        if unitId == 987651 then
            return { coords = coordinates }
        end
        return oldUnit(self, unitId)
    end
    local complete = db:GetQuestLocations(987650, false, 12)
    local bounded = db:GetQuestLocations(987650, false, 12, 8)
    local collected = target:CollectLocations({ questId = 987650 }, 12, false)
    db.GetQuestObjectiveSources = oldSources
    db.GetUnit = oldUnit
    return table.getn(complete) == 205 and table.getn(collected) == 205
        and table.getn(bounded) == 8
end)()"""))

# The bag scan is round-robined one bag per tick and only publishes a whole
# cycle, so a partial pass must never look like empty bags.
rt.execute("PQ_TEST_BAGS = { [0] = {} }; PandaQuest:GetModule('BagItems'):Invalidate()")
rt.execute("PQ_TEST_TICK(1.0, 8)")
check("an empty-bag cycle publishes a readable, empty set", rt.eval("""(function()
    local bags = PandaQuest:GetModule('BagItems')
    return bags.available == true and bags:Carries(16333) == false
end)()"""))
rt.execute("PQ_TEST_BAGS[0][3] = 16333; PandaQuest:GetModule('BagItems'):Invalidate()")
rt.execute("PQ_TEST_TICK(1.0, 8)")
check("looting the required item is observed", rt.eval(
    "PandaQuest:GetModule('BagItems'):Carries(16333) == true"))
check("the carried-set token moves only when membership changes", rt.eval("""(function()
    local bags = PandaQuest:GetModule('BagItems')
    local before = bags:GetToken()
    PQ_TEST_TICK(1.0, 8)
    return bags:GetToken() == before
end)()"""))
check("an unreadable container API reports unknown, not empty", rt.eval("""(function()
    local bags = PandaQuest:GetModule('BagItems')
    PQ_TEST_BAG_API = false
    bags:Invalidate()
    PQ_TEST_TICK(1.0, 8)
    local unknown = bags.available == false and bags:Carries(16333) == nil
    PQ_TEST_BAG_API = true
    bags:Invalidate()
    PQ_TEST_TICK(1.0, 8)
    return unknown and bags:Carries(16333) == true
end)()"""))
check("adding a carried-item target does not mutate cached static locations", rt.eval("""(function()
    local db = PandaQuest:GetModule('Database')
    local target = PandaQuest:GetModule('QuestTarget')
    local static = db:GetQuestLocations(6395, false, 85, 200)
    local before = table.getn(static)
    local collected = target:CollectLocations({ questId = 6395 }, 85, false)
    local again = db:GetQuestLocations(6395, false, 85, 200)
    -- The bounded location cache may legitimately evict the first table in a
    -- long full-suite run. Identity across that eviction is not the contract;
    -- leaving both static answers unchanged is.
    return collected ~= static and table.getn(again) == before
        and table.getn(static) == before
        and table.getn(collected) > before
end)()"""))

# End to end on the real record that produced the report: with the quest
# accepted and the bags empty the map must show Samuel Fipps and nothing else,
# and once the remains are carried it must show Marla's Grave and nothing else
# -- the step moves, it does not accumulate.
rt.execute("""
    PQ_TEST_RESTORE_LOG = PQ_TEST_LOG
    PQ_TEST_MAP_FILE = "Tirisfal"
    PQ_TEST_ZONE_NAME = "Tirisfal Glades"
    PQ_TEST_SUBZONE_NAME = "Deathknell"
    PQ_TEST_LOG = {
        { "Tirisfal Glades", 0, nil, 1, nil, nil },
        { "Marla's Last Wish", 5, nil, nil, nil, nil,
          { { "Samuel's Remains: 0/1", "item", nil } } },
    }
    PQ_TEST_BAGS = { [0] = {} }
    PandaQuest:GetModule('BagItems'):Invalidate()
    PandaQuest:GetModule('QuestState'):Scan()
    PQ_TEST_TICK(1.0, 10)
    PQ_TEST_AREAS_WITHOUT = PandaQuest:GetModule('WorldMapPins').areaVisibleCount
    PQ_TEST_BAGS[0][1] = 16333
    -- The client moves the counter the moment the item is looted, and that is
    -- what tells the addon the acquisition half of the step is over. A fixture
    -- that leaves the line at 0/1 would be describing a client that does not
    -- exist, and would keep Samuel Fipps on the map for ever.
    PQ_TEST_LOG[2][7][1] = { "Samuel's Remains: 1/1", "item", 1 }
    PandaQuest:GetModule('BagItems'):Invalidate()
    PandaQuest:GetModule('QuestState'):Scan()
    PQ_TEST_TICK(1.0, 10)
    PQ_TEST_AREAS_WITH = PandaQuest:GetModule('WorldMapPins').areaVisibleCount
""")
check("without the remains the map draws only Samuel Fipps", rt.eval(
    "PQ_TEST_AREAS_WITHOUT == 1"))
check("carrying the remains swaps Samuel Fipps for the grave", rt.eval(
    "PQ_TEST_AREAS_WITH == 1"))
check("the one remaining area is the grave, not the creature", rt.eval("""(function()
    local target = PandaQuest:GetModule('QuestTarget')
    local found = target:CollectLocations(
        { questId = 6395, objectives = PandaQuest:GetModule('QuestState')
            :GetOrderedQuests()[1].objectives }, 85, false)
    if table.getn(found) ~= 1 then return false end
    return found[1].sourceType == 'object' and found[1].sourceId == 178090
end)()"""))
# The bag alone must not be allowed to decide it. A quest that counts the item
