# --- The collapsed-header trap ----------------------------------------------------
check("a collapsed header does not drop the followed quest", rt.eval("""(function()
    local state = PandaQuest:GetModule('QuestState')
    local main = PandaQuest:GetModule('MainQuest')
    local before = main:Get()

    -- Collapse the header: the client stops listing the quests under it, so
    -- the followed quest vanishes from the log without being turned in.
    local saved = { }
    for i = 1, table.getn(PQ_TEST_LOG) do saved[i] = PQ_TEST_LOG[i] end
    PQ_TEST_LOG[1][5] = 1
    PQ_TEST_LOG[2] = nil
    PQ_TEST_LOG[3] = nil
    state:Scan()
    main:Validate()
    local survived = main:Get() == before

    for i = 1, table.getn(saved) do PQ_TEST_LOG[i] = saved[i] end
    PQ_TEST_LOG[1][5] = nil
    state:Scan()
    return survived and before ~= nil
end)()"""))

check("the followed quest is dropped once it really leaves the log", rt.eval("""(function()
    local state = PandaQuest:GetModule('QuestState')
    local main = PandaQuest:GetModule('MainQuest')

    local saved = PQ_TEST_LOG[2]
    table.remove(PQ_TEST_LOG, 2)
    state:Scan()
    main:Validate()
    local dropped = main:Get() == nil

    table.insert(PQ_TEST_LOG, 2, saved)
    state:Scan()
    PQ_TEST_REFRESH_NATIVE_QUEST_UI()
    return dropped
end)()"""))

