# A complete quest keeps its log-order number and places the bundled checkmark
# beside it, rather than replacing the number or overwriting the title colour.
# Its objectives are all satisfied, so listing them -- or a separate "ready to
# turn in" line -- only makes the window taller without adding information.
check("a complete quest keeps its level colour and number plus complete icon, "
      "and has no objective lines below it",
      rt.eval("""(function()
    local questRow
    local index = 1
    while getglobal('PandaQuestTrackerRowquest' .. index) do
        local row = getglobal('PandaQuestTrackerRowquest' .. index)
        if row:IsShown() and string.find(row.fontString.text, 'Sharptalon', 1, true) then
            questRow = row
        end
        index = index + 1
    end
    if questRow == nil then return false end
    local red, green, blue = PandaQuest.Client.GetQuestLevelColor(questRow.pandaQuestSubject.level)
    local color = questRow.fontString.color
    if color == nil or color[1] ~= red or color[2] ~= green or color[3] ~= blue then
        return false
    end
    local number = questRow.pandaQuestQuestNumber
    local mark = questRow.pandaQuestQuestMark
    if number == nil or number:IsShown() ~= true
        or number.path ~= PandaQuest.Client.WORLD_MAP_QUEST_POI_NUMBER_TEXTURE
        or questRow.pandaQuestQuestNumberValue ~= 2
        or mark == nil or mark:IsShown() ~= true
        or mark.path ~= 'Interface\\\\AddOns\\\\pandaQuest\\\\media\\\\Textures\\\\Map\\\\Pins\\\\CompleteQuestIcon' then
        return false
    end
    local shown = 0
    index = 1
    while getglobal('PandaQuestTrackerRowobjective' .. index) do
        local row = getglobal('PandaQuestTrackerRowobjective' .. index)
        if row:IsShown() then
            if string.find(row.fontString.text, 'Sharptalon', 1, true) then return false end
            if row.fontString.text == 'Ready to turn in' then return false end
            shown = shown + 1
        end
        index = index + 1
    end
    -- Kobold Camp Cleanup and Poor Old Blanchy, one objective each.
    return shown == 2
end)()"""))

check("an objective with no counter gets no progress bar", rt.eval("""(function()
    local index = 1
    while getglobal('PandaQuestTrackerRowobjective' .. index) do
        local row = getglobal('PandaQuestTrackerRowobjective' .. index)
        if row:IsShown() and row.fontString.text == 'Blanchy watered' then
            return row.pandaQuestBarTrack:IsShown() == false
        end
        index = index + 1
    end
    return false
end)()"""))

