print("decorated quest log titles")
# A level-prefixing addon (CT_QuestLevels and its many copies) or the client
# itself can hand back "[24] Weapons of Choice" instead of "Weapons of Choice".
# The title is the only join between a quest log row and the bundled database,
# so a decoration that survives into the matcher costs EVERY quest its identity
# -- reported 2026-08-23 on a ruRU client with quests 879 and 893 drawing
# nothing while pfQuest drew them.
check("clean title is returned unchanged",
      rt.eval("PandaQuest.Client.CleanQuestTitle('Weapons of Choice') == 'Weapons of Choice'"))
check("level prefix is stripped",
      rt.eval("PandaQuest.Client.CleanQuestTitle('[24] Weapons of Choice') == 'Weapons of Choice'"))
check("level prefix variants are stripped",
      rt.eval("""PandaQuest.Client.CleanQuestTitle('[24+] A') == 'A'
        and PandaQuest.Client.CleanQuestTitle('[24D] A') == 'A'
        and PandaQuest.Client.CleanQuestTitle('[15G5] A') == 'A'"""))
check("a doubled prefix and colour escapes are stripped",
      rt.eval("PandaQuest.Client.CleanQuestTitle('|cff40c040[24]|r [24] A') == 'A'"))
check("a bracket group that is not a level is left alone",
      rt.eval("PandaQuest.Client.CleanQuestTitle('[Unused] A') == '[Unused] A'"),
      "real upstream titles start with a non-numeric bracket group")
check("a title that is nothing but a prefix keeps the client's string",
      rt.eval("PandaQuest.Client.CleanQuestTitle('[24]') == '[24]'"))
check("whitespace trim does not count as a decoration",
      rt.eval("""(function()
        local cleaned, decorated = PandaQuest.Client.CleanQuestTitle('  A  ')
        return cleaned == 'A' and not decorated
      end)()"""))

# End to end: the same quest, decorated and undecorated, must resolve to the
# same database record and draw the same map tiles.
def barrens_scan(title):
    rt.execute("""
        PQ_TEST_MAP_FILE = "Barrens"
        PQ_TEST_ZONE_NAME = "The Barrens"
        PQ_TEST_LOG = {
            { "The Barrens", 0, nil, 1, nil, nil },
            { "%s", 24, nil, nil, nil, nil,
              { { "Razormane Backstabber: 0/1", "item", nil } } },
        }
        PandaQuest:GetModule('QuestMatch'):ClearCache()
        PandaQuest:GetModule('QuestState'):Scan()
        PandaQuest:GetModule('WorldMapPins'):Refresh()
    """ % title)
    return (rt.eval("PandaQuest:GetModule('QuestState'):GetOrderedQuests()[1].questId"),
            rt.eval("PandaQuest:GetModule('QuestState'):GetOrderedQuests()[1].title"),
            rt.eval("PandaQuest:GetModule('WorldMapPins'):GetStatus().areaVisible"))

before = rt.eval("PandaQuest.Client.GetQuestTitleDecorationCount()")
