print("settings: pandaUI's settings groups turn the page into a submenu")

# The checks above ran against an pandaUI mock without RegisterSettingsGroup,
# which is the single tabbed row. With groups available, the sidebar rows are
# the tabs: one "PandaQuest" group and one page per section, and no internal
# tab strip on either page. The internal tabs' globals are cleared first so a
# strip left over from the tabbed build cannot satisfy "there is none".
rt.execute("""
    PandaUI.tabs = {}
    PandaUI.groups = {}
    PandaUI.opened = nil
    local function Taken(id)
        for _, entry in ipairs(PandaUI.groups) do
            if entry.id == id then return true end
        end
        for _, entry in ipairs(PandaUI.tabs) do
            if entry.id == id then return true end
        end
        return false
    end
    function PandaUI.RegisterSettingsGroup(id, label, options)
        if Taken(id) then return nil end
        local entry = { id = id, label = label, options = options }
        table.insert(PandaUI.groups, entry)
        return entry
    end
    function PandaUI.RegisterSettingsTab(id, label, build, options)
        if Taken(id) then return nil end
        local entry = { id = id, label = label, build = build, options = options }
        table.insert(PandaUI.tabs, entry)
        return entry
    end
    setglobal('PandaQuestSettingsGeneralTab', nil)
    setglobal('PandaQuestSettingsMobTrackingTab', nil)
    setglobal('PandaQuestSettingsDialogueTab', nil)

    local settings = PandaQuest:GetModule('Settings')
    settings.host = nil
    settings.hostWaited = 0
    settings.registered = nil
    settings.hostLayout = nil
    settings.activePageTab = 'general'
    settings:OnEnable()
    PQ_TEST_TICK(0.5, 3)
""")
check("pandaUI with settings groups hosts PandaQuest as a submenu",
      rt.eval("PandaQuest:GetModule('Settings').host == 'pandaui' "
              "and PandaQuest:GetModule('Settings').hostLayout == 'group'"))
check("one PandaQuest group holds General, Quest dialogue and Mob tracking pages", rt.eval("""(function()
    local groups, tabs = PandaUI.groups, PandaUI.tabs
    return table.getn(groups) == 1 and groups[1].id == 'pandaquest'
        and groups[1].label == 'PandaQuest'
        and groups[1].options.icon
            == 'Interface\\\\AddOns\\\\pandaQuest\\\\media\\\\Textures\\\\Settings\\\\PQ_logo'
        and groups[1].options.watermark
            == 'Interface\\\\AddOns\\\\pandaQuest\\\\media\\\\Textures\\\\Settings\\\\panda-quest'
        and table.getn(tabs) == 3
        and tabs[1].id == 'pandaquest.general'
        and tabs[1].label == PandaQuest.L('SETTINGS_TAB_GENERAL')
        and tabs[1].options.parent == 'pandaquest'
        and tabs[1].options.after == 'pandaquest'
        and tabs[2].id == 'pandaquest.dialogue'
        and tabs[2].label == PandaQuest.L('SETTINGS_TAB_DIALOGUE')
        and tabs[2].options.parent == 'pandaquest'
        and tabs[2].options.after == 'pandaquest.general'
        and tabs[3].id == 'pandaquest.mobs'
        and tabs[3].label == PandaQuest.L('SETTINGS_TAB_MOB_TRACKING')
        and tabs[3].options.parent == 'pandaquest'
        and tabs[3].options.after == 'pandaquest.dialogue'
        and tabs[1].widgets == nil and tabs[2].widgets == nil and tabs[3].widgets == nil
end)()"""))

