def status_line_contains(fragment):
    return rt.eval("""(function()
    for _, region in ipairs(PandaQuestSettingsContent.regions) do
        if region.text and string.find(region.text, '%s', 1, true) then
            return true
        end
    end
    return false
end)()""" % fragment)


