print("interface language")
# Every catalog is already loaded (the TOC lists them), so this exercises the
# lookup rather than the files: each language is activated in turn and asked
# for a key that carries a format placeholder and a key that does not.
check("four languages are registered", rt.eval(
    "table.getn(PandaQuest.GetLanguages()) == 4"))
# The flag row in the standalone window's header. It exists only there: with
# pandaUI hosting the page, the language is set in pandaUI and a second
# selector would be two controls writing one value.
check("the standalone settings header carries one flag per language", rt.eval(
    "getglobal('PandaQuestSettingsLanguageenUS') ~= nil "
    "and getglobal('PandaQuestSettingsLanguagefrFR') ~= nil "
    "and getglobal('PandaQuestSettingsLanguageruRU') ~= nil "
    "and getglobal('PandaQuestSettingsLanguagezhCN') ~= nil"))
check("a flag button draws its texture and no chrome of its own", rt.eval(
    "PandaQuestSettingsLanguagefrFR.pandaQuestIcon ~= nil "
    "and PandaQuestSettingsLanguagefrFR.pandaQuestBackground == nil"))
# Explicitly, never through the parent: nothing here may rely on a window's
# visibility reaching its children, and a flag outliving its closed window
# would sit on the screen with nothing behind it.
rt.execute("PandaQuest:GetModule('Settings'):Close()")
check("the flags hide with the window", rt.eval(
    "PandaQuestSettingsLanguagefrFR:IsShown() == false"))
rt.execute("PandaQuest:GetModule('Settings'):Open()")
check("and come back with it", rt.eval(
    "PandaQuestSettingsLanguagefrFR:IsShown() == true"))
# A frame here keeps only its LAST SetPoint, which for the handle is the
# TOPRIGHT edge -- the one the flag row pushes inwards.
check("the drag handle is inset so the flags stay clickable", rt.eval(
    "PandaQuestSettingsHandle.point[1] == 'TOPRIGHT' "
    "and PandaQuestSettingsHandle.point[4] == -(12 + 4 * (18 + 3))"),
    str(rt.eval("PandaQuestSettingsHandle.point[4]")))
check("English is the resolved default with no pandaUI present", rt.eval(
    "PandaQuest.GetLanguage() == 'enUS' "
    "and PandaQuest.IsLanguageFollowingPandaUI() == false"))
check("a flag texture path is rebuilt at runtime, never stored", rt.eval(
    "PandaQuest.FlagTexture('frFR') ~= nil "
    "and PandaQuestDB.language ~= nil "
    "and string.find(PandaQuestDB.language, '\\\\', 1, true) == nil"))

# French is folded to plain ASCII on the way out of the generator, so the
# sample is "quetes" and not the accented spelling -- see ascii_fold in
# tools/locale/gen_locales.py for why the client's font forces that.
for code, sample in (("frFR", "quetes"), ("ruRU", "задани"), ("zhCN", "任务")):
    rt.execute("PandaQuest.SetLanguage('%s')" % code)
    check("%s activates and answers in its own language" % code, rt.eval(
        "PandaQuest.GetLanguage() == '%s' "
        "and string.find(PandaQuest.L('CMD_HELP_TRACKER'), '%s', 1, true) ~= nil"
        % (code, sample)),
        ascii(rt.eval("PandaQuest.L('CMD_HELP_TRACKER')")))
    check("%s keeps the format argument" % code, rt.eval(
        "string.find(PandaQuest.L('CMD_UNKNOWN', 'zzz'), 'zzz', 1, true) ~= nil"),
        ascii(rt.eval("PandaQuest.L('CMD_UNKNOWN', 'zzz')")))

# The fold is a shipping rule, not a one-off cleanup: an accented glyph that
# creeps back into the French catalog by hand draws as a blank box in game,
# which is silent. Checked over the whole catalog rather than one string.
french_accented = [line.strip()[:60] for line
                   in io.open(os.path.join(ADDONS, "pandaQuest", "Locales",
                                           "frFR.lua"), encoding="utf-8")
                   if any(0x80 <= ord(ch) < 0x370 for ch in line)]
check("no French string carries a glyph the client's font cannot draw",
      french_accented == [], " | ".join(french_accented[:3]))

# The Russian rule is the only one with three forms. 11 and 21 are the two
# counts that separate it from a naive "1 vs the rest": 21 is ONE, 11 is MANY.
rt.execute("PandaQuest.SetLanguage('ruRU')")
russian_rows = {n: str(rt.eval("PandaQuest.LN('CMD_TRACKER_ROWS', %d)" % n))
                for n in (1, 2, 5, 11, 21)}
check("Russian picks ONE / FEW / MANY by count",
      russian_rows == {
          1: "1 строка",
          2: "2 строки",
          5: "5 строк",
          11: "11 строк",
          21: "21 строка",
      },
      # ascii(): this script prints to a console that is not necessarily UTF-8.
      ascii(russian_rows))

# A key with no entry must come back as itself, not as an empty label -- that
# is the only failure mode a translator can actually spot in game.
check("an unknown key returns itself", rt.eval(
    "PandaQuest.L('PQ_TEST_NO_SUCH_KEY') == 'PQ_TEST_NO_SUCH_KEY'"))
# Non-English falls back to the English entry rather than to the raw key.
check("a language without an entry falls back to English", rt.eval(
    "PandaQuest.L('CMD_HELP_TRACKER_OBJECTIVES') "
    "== '/pq tracker objectives all|tracked|none'"))

rt.execute("PandaQuest.SetLanguage('enUS')")
check("English can be selected back", rt.eval("PandaQuest.GetLanguage() == 'enUS'"))

# Following pandaUI. The harness has no pandaUI, which is the standalone case
# already covered above; these two put one in place and re-run the resolution
# the way a real load would, once through each of its two reads.
#
# The second read (the SavedVariables global) is the one that matters most: it
# is what makes the language correct on the FIRST frame, before pandaUI's own
# Initialise has run and while its GetLanguage would still answer with its
# compiled-in default.
rt.execute("""
    local locale = PandaQuest:GetModule('Locale')

    -- pandaUI present but not yet initialised: only its saved value can answer.
    PandaUI = { ready = false, GetLanguage = function() return 'enUS' end }
    PandaUIProfiles = { language = 'ruRU' }
    locale.settled = false
    locale.followsPandaUI = false
    locale:Resolve(false)
    PQ_TEST_FOLLOW_EARLY = PandaQuest.GetLanguage()
    PQ_TEST_FOLLOW_EARLY_FLAG = PandaQuest.IsLanguageFollowingPandaUI()

    -- The player's own stored choice must not be able to override it, and the
    -- flag row must not be able to write one either.
    PQ_TEST_FOLLOW_REFUSED = PandaQuest.SetLanguage('frFR')

    -- pandaUI initialised: the getter is authoritative from here on.
    PandaUI.ready = true
    PandaUI.GetLanguage = function() return 'zhCN' end
    locale.settled = false
    locale:Resolve(false)
    PQ_TEST_FOLLOW_READY = PandaQuest.GetLanguage()

    -- Back to standalone for anything that runs after this.
    PandaUI = nil
    PandaUIProfiles = nil
    locale.settled = true
    locale.followsPandaUI = false
    PandaQuest.SetLanguage('enUS')
""")
check("an uninitialised pandaUI is still read, through its saved language",
      rt.eval("PQ_TEST_FOLLOW_EARLY == 'ruRU' and PQ_TEST_FOLLOW_EARLY_FLAG == true"),
      str(rt.eval("PQ_TEST_FOLLOW_EARLY")))
check("the flag row cannot write a language pandaUI owns",
      rt.eval("PQ_TEST_FOLLOW_REFUSED == false"))
check("an initialised pandaUI answers through GetLanguage",
      rt.eval("PQ_TEST_FOLLOW_READY == 'zhCN'"),
      str(rt.eval("PQ_TEST_FOLLOW_READY")))
check("removing pandaUI returns the language to this addon",
      rt.eval("PandaQuest.GetLanguage() == 'enUS' "
              "and PandaQuest.IsLanguageFollowingPandaUI() == false"))

check("a theme's larger button font re-fits the same label instead of wrapping it", rt.eval("""
(function()
    local C = PandaQuest.Client
    local frame, button = PandaQuestDialogueFrame, PandaQuestDialogueAction
    local entry = { text = 'Accept Quest', action = 'accept' }
    local saved = button.pandaQuestSpec
    C.ShowQuestDialogueButton(frame, button, C.QUEST_DIALOGUE_HORDE_LIGHT.ACTION_BUTTON, entry)
    C.SettleQuestDialogueLabels()
    C.SettleQuestDialogueLabels()
    C.SettleQuestDialogueLabels()
    C.SettleQuestDialogueLabels()
    local settled = C.QUEST_DIALOGUE_FITS.pending[button.pandaQuestLabel] == nil
    C.ShowQuestDialogueButton(frame, button, C.QUEST_DIALOGUE_ALLIANCE_LIGHT.ACTION_BUTTON, entry)
    local refit = C.QUEST_DIALOGUE_FITS.pending[button.pandaQuestLabel] == true
    if saved then C.ShowQuestDialogueButton(frame, button, saved, entry) end
    return settled and refit
end)()
"""))

